//go:build !astro_lowmem
// +build !astro_lowmem

// 被测契约：zz_*_lowmem.go 由同名默认文件机械替换得到，内容必须与生成结果一致；重新生成需设环境变量。
package semianalytic

import (
	"os"
	"strings"
	"testing"
)

//go:generate env ASTRO_REGENERATE_LOWMEM_SOURCES=1 go test -run=TestLowmemSourcesUpToDate -count=1
const lowmemGenerateEnv = "ASTRO_REGENERATE_LOWMEM_SOURCES"

// 默认文件只能经包内只读表入口取模型，换成 Flash 版本后逐位一致。
var lowmemReplacements = []string{
	"//go:build !astro_lowmem\n// +build !astro_lowmem\n", "//go:build astro_lowmem\n// +build astro_lowmem\n\n// Code generated by lowmem_generate_test.go; DO NOT EDIT.\n",
	"planets.Default()", "planets.FlashDefault()",
	"planets.Fast()", "planets.FlashFast()",
	"lunar.Default()", "lunar.FlashDefault()",
	"lunar.Fast()", "lunar.FlashFast()",
	"*planets.Model", "*planets.FlashModel",
	"*lunar.Model", "*lunar.FlashModel",
}

var lowmemSources = []string{"apparent.go", "ofdate.go", "state.go"}

func lowmemTarget(src string) string { return "zz_" + strings.TrimSuffix(src, ".go") + "_lowmem.go" }

func TestLowmemSourcesUpToDate(t *testing.T) {
	regenerate := os.Getenv(lowmemGenerateEnv) == "1"
	r := strings.NewReplacer(lowmemReplacements...)
	for _, src := range lowmemSources {
		b, err := os.ReadFile(src)
		if err != nil {
			t.Fatal(err)
		}
		if !strings.HasPrefix(string(b), lowmemReplacements[0]) {
			t.Fatalf("%s must start with the !astro_lowmem build constraint", src)
		}
		want := r.Replace(string(b))
		dst := lowmemTarget(src)
		if regenerate {
			if err := os.WriteFile(dst, []byte(want), 0o644); err != nil {
				t.Fatal(err)
			}
		}
		got, err := os.ReadFile(dst)
		if err != nil {
			t.Fatal(err)
		}
		if string(got) != want {
			t.Errorf("%s is stale; regenerate with %s=1 go test -run=%s", dst, lowmemGenerateEnv, t.Name())
		}
	}
}
